import json, os, subprocess, sys, time
from pathlib import Path
root = Path(sys.argv[1])
reference = None

def compare(value):
 global reference
 rows = {r['key']: r for r in value['rows']}
 if reference is None:
  reference = rows
  return
 assert rows.keys() == reference.keys()
 for key, row in rows.items():
  a, b = reference[key]['oracle'], row['oracle']
  for field in ('output', 'plan_debug', 'warnings'):
   assert a[field] == b[field], (key, field)
  if isinstance(a['height'], dict):
   for field in ('needed_bits', 'warnings'):
    assert a['height'][field] == b['height'][field], (key, 'height', field)

for batch in range(5):
 for label in (('base', 'candidate') if batch % 2 == 0 else ('candidate', 'base')):
  env = dict(os.environ, SHODO_BALANCE_SAMPLES='3')
  env.pop('SHODO_BALANCE_CASE', None)
  if batch % 2: env['SHODO_BALANCE_REVERSE'] = '1'
  else: env.pop('SHODO_BALANCE_REVERSE', None)
  name = f'time-{batch}-{label}'
  started = time.monotonic()
  with (root / (name + '.json')).open('w') as out, (root / (name + '.stderr')).open('w') as err:
   proc = subprocess.run(['taskset', '-c', '0', str(root / 'bin' / (label + '-time'))], env=env, stdout=out, stderr=err)
  if proc.returncode:
   print((root / (name + '.stderr')).read_text()[:2000], flush=True)
   raise SystemExit(proc.returncode)
  value = json.loads((root / (name + '.json')).read_text())
  compare(value)
  print(f'{name}: {len(value["rows"])} exact output/warning matches, {time.monotonic()-started:.2f}s', flush=True)
print('5 alternating pairs x 3 samples: 15 samples/revision/case; all recursive output, ends, heights and ordered warnings identical', flush=True)

