import json,sys,hashlib,statistics,re
from pathlib import Path
root=Path(sys.argv[1]); repo=Path(sys.argv[2]); reference={}; accumulated={}; pairs={}
def digest(v):return hashlib.sha256(json.dumps(v,sort_keys=True,separators=(',',':'),ensure_ascii=False).encode()).hexdigest()
def oracle(row):
 o=row['oracle'];h=o['height']
 return {'output_sha256':digest(o['output']), 'plan_debug':o['plan_debug'], 'warnings':o['warnings'], 'height':None if h is None else {k:h[k] for k in ('needed_bits','warnings')}}
def validate(row):
 key=row['key'];o=oracle(row)
 if key not in reference:reference[key]=o
 else:assert reference[key]==o,key
 return o
batches=[]
for i in range(5):
 for revision in ('base','candidate'):
  path=root/f'time-{i}-{revision}.json'; value=json.loads(path.read_text());rows=[]
  for row in value['rows']:
   validate(row)
   samples={scope:[sample[scope]['ns'] for sample in row['samples']] for scope in ('build','plan','accepted','output_release','plan_release','paragraph_release','context_release')}
   for scope,vals in samples.items():
    accumulated.setdefault((row['key'],scope),{}).setdefault(revision,[]).extend(vals)
    pairs.setdefault((row['key'],scope),{}).setdefault(revision,[]).append(statistics.median(vals))
   rows.append({'key':row['key'],'ns':samples})
  batches.append({'batch':i,'revision':revision,'reverse':value['reverse'],'source_file_sha256':hashlib.sha256(path.read_bytes()).hexdigest(),'rows':rows})
